$Corp = "OU=GraceLab,DC=corp,DC=gracelab,DC=com"
New-ADOrganizationalUnit -Name "GraceLab" -Path "DC=corp,DC=gracelab,DC=com"
"Users","Workstations","Groups","Disabled Users" | ForEach-Object {
    New-ADOrganizationalUnit -Name $_ -Path $Corp
}
"IT","HR","Sales" | ForEach-Object {
    New-ADOrganizationalUnit -Name $_ -Path "OU=Users,$Corp"
}
